// The Architectural Flow of File Handling:
// 1. Application (Your Java Logic)
// 2. Stream (The data flow channel)
// 3. Buffer (Temporary RAM storage to speed things up)
// 4. Disk (The physical hard drive)

import java.io.File;

public class FileDemo {
    public static void main(String[] args) {
        // This ONLY creates a string path in RAM. It does not touch the disk!
        File file = new File("student_records.txt");

        // Metadata Methods:
        System.out.println("Exists   : " + file.exists());
        System.out.println("Name     : " + file.getName());
        System.out.println("Is File  : " + file.isFile());
        System.out.println("Can Read : " + file.canRead());
    }
}

import java.io.File;
import java.io.IOException;

public class DiskOps {
    public static void main(String[] args) {
        File file = new File("temp_cache.txt");

        try {
            // 1. SAFE CREATION
            if (file.createNewFile()) {
                System.out.println("File physically created on disk.");
            } else {
                System.out.println("Ignored: File already exists.");
            }

            // 2. SAFE DELETION
            if (file.exists()) {
                file.delete();
            }
        } catch (IOException e) {
            System.out.println("Disk Error: " + e.getMessage());
        }
    }
}

import java.io.FileWriter;
import java.io.IOException;

public class WriteDemo {
    public static void main(String[] args) {
        // The 'true' flag turns on APPEND MODE. 
        // Without it, the file is totally erased (OVERWRITE MODE).
        try (FileWriter writer = new FileWriter("logs.txt", true)) {
            writer.write("System Booted at 09:00 AM\n");
            writer.write("User login: Usama\n");

            // CRITICAL: Flushes data from RAM to Disk
            writer.close(); 
        } catch (IOException e) {
            System.out.println("Write failed.");
        }
    }
}

import java.io.File;
import java.io.FileNotFoundException;
import java.util.Scanner;

public class ReadWithScanner {
    public static void main(String[] args) {
        try {
            File file = new File("student_records.txt");
            Scanner scanner = new Scanner(file);

            // CRITICAL: Always check if a next line exists BEFORE reading it.
            while (scanner.hasNextLine()) {
                String line = scanner.nextLine(); 
                System.out.println(line);
            }

            scanner.close();
        } catch (FileNotFoundException e) {
            System.out.println("File not found: " + e.getMessage());
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class FastReader {
    public static void main(String[] args) {
        // Wrap a standard FileReader inside a high-speed BufferedReader
        try (BufferedReader br = new BufferedReader(new FileReader("huge_data.csv"))) {
            String line;

            // readLine() reads a full row. It returns 'null' when the file is empty.
            while ((line = br.readLine()) != null) {
                System.out.println(line);
            }
        } catch (IOException e) {
            System.out.println("Read error.");
        }
    }
}

import java.nio.file.*;
import java.io.IOException;
import java.util.List;

public class ModernFileOps {
    public static void main(String[] args) {
        // 1. Use Paths.get() instead of new File()
        Path myFile = Paths.get("config.yaml");

        try {
            // 2. Write an entire list of strings in ONE line!
            Files.write(myFile, List.of("port: 8080", "debug: true"));

            // 3. Read the entire file into a List in ONE line!
            List<String> data = Files.readAllLines(myFile);
            data.forEach(System.out::println);

            // 4. Copy the file safely (replaces existing backup if found)
            Files.copy(myFile, Paths.get("backup.yaml"), StandardCopyOption.REPLACE_EXISTING);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

// Notice the parenthesis ( ) after the 'try' keyword.
// Any class that implements 'AutoCloseable' can go inside here.
try (BufferedReader reader = new BufferedReader(new FileReader("data.txt"));
     BufferedWriter writer = new BufferedWriter(new FileWriter("output.txt"))) {

    String line;
    while ((line = reader.readLine()) != null) {
        writer.write(line.toUpperCase());
        writer.newLine();
    }

// No finally { writer.close(); } block is needed! Java handles it invisibly.
} catch (IOException e) {
    System.err.println("System Failure: " + e.getMessage());
}

