// 1. The Class must implement Serializable (It acts as a permission flag)
class Student implements java.io.Serializable {
    int id;
    String name;
}

// 2. Saving the Object (Serialization)
try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("student.dat"))) {
    Student s = new Student(101, "Usman");
    oos.writeObject(s);
}

// 3. Loading the Object (Deserialization)
try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("student.dat"))) {
    Student s = (Student) ois.readObject();
}

try (RandomAccessFile raf = new RandomAccessFile("data.txt", "rw")) {
    // Instantly jump 100 bytes into the file
    raf.seek(100);

    // Read the exact byte at that position
    char c = (char) raf.read();
}

